import { parseAddr, toAddr } from "./addr.mjs";

const REF = /^\$?[A-Za-z]{1,3}\$?[1-9]\d*$/;
const TOKEN = /\s*(?:(\d+\.?\d*(?:[eE][+-]?\d+)?|\.\d+(?:[eE][+-]?\d+)?)|"((?:[^"]|"")*)"|(\$?[A-Za-z_][A-Za-z0-9_.]*\$?\d*)|(<>|<=|>=|[-+*\/^&=<>(),:]))/y;

function tokenize(text) {
  const out = [];
  let pos = 0;
  while (pos < text.length) {
    if (/^\s*$/.test(text.slice(pos))) break;
    TOKEN.lastIndex = pos;
    const m = TOKEN.exec(text);
    if (!m) throw new SyntaxError(`unexpected character at ${pos}: ${text.slice(pos).trim()[0]}`);
    pos = TOKEN.lastIndex;
    if (m[1] !== undefined) out.push({ k: "num", v: Number(m[1]) });
    else if (m[2] !== undefined) out.push({ k: "str", v: m[2].replace(/""/g, '"') });
    else if (m[3] !== undefined) out.push({ k: "id", v: m[3] });
    else out.push({ k: "op", v: m[4] });
  }
  return out;
}

const norm = (s) => s.replace(/\$/g, "").toUpperCase();

export function parseFormula(text) {
  const toks = tokenize(String(text));
  let i = 0;
  const peekOp = (...ops) => toks[i] && toks[i].k === "op" && ops.includes(toks[i].v);
  const expectOp = (op) => {
    if (!peekOp(op)) throw new SyntaxError(`expected ${op}`);
    i++;
  };
  const left = (next, ops) => () => {
    let node = next();
    while (peekOp(...ops)) {
      const op = toks[i++].v;
      node = { t: "bin", op, l: node, r: next() };
    }
    return node;
  };
  const primary = () => {
    const tok = toks[i++];
    if (!tok) throw new SyntaxError("unexpected end of formula");
    if (tok.k === "num") return { t: "num", v: tok.v };
    if (tok.k === "str") return { t: "str", v: tok.v };
    if (tok.k === "op") {
      if (tok.v !== "(") throw new SyntaxError(`unexpected ${tok.v}`);
      const e = comparison();
      expectOp(")");
      return e;
    }
    const up = tok.v.toUpperCase();
    if (peekOp("(")) {
      if (!/^[A-Z_][A-Z0-9_.]*$/.test(up)) throw new SyntaxError(`bad function name ${tok.v}`);
      i++;
      const args = [];
      if (!peekOp(")")) {
        do args.push(comparison()); while (peekOp(",") && i++);
      }
      expectOp(")");
      return { t: "call", name: up, args };
    }
    if (REF.test(tok.v)) {
      const a = norm(tok.v);
      if (peekOp(":")) {
        i++;
        const t2 = toks[i++];
        if (!t2 || t2.k !== "id" || !REF.test(t2.v)) throw new SyntaxError("bad range");
        const p = parseAddr(a), q = parseAddr(norm(t2.v));
        return {
          t: "range",
          c1: Math.min(p.col, q.col), c2: Math.max(p.col, q.col),
          r1: Math.min(p.row, q.row), r2: Math.max(p.row, q.row),
        };
      }
      return { t: "ref", addr: a };
    }
    if (up === "TRUE") return { t: "bool", v: true };
    if (up === "FALSE") return { t: "bool", v: false };
    return { t: "name", name: up };
  };
  const unary = () => {
    if (peekOp("-", "+")) {
      const op = toks[i++].v;
      return { t: "un", op, e: unary() };
    }
    return primary();
  };
  const power = left(unary, ["^"]);
  const term = left(power, ["*", "/"]);
  const sum = left(term, ["+", "-"]);
  const concat = left(sum, ["&"]);
  const comparison = left(concat, ["=", "<>", "<", ">", "<=", ">="]);
  const ast = comparison();
  if (i < toks.length) throw new SyntaxError(`unexpected ${toks[i].v}`);
  return ast;
}

function rangeAddrs(n) {
  const out = [];
  for (let r = n.r1; r <= n.r2; r++) for (let c = n.c1; c <= n.c2; c++) out.push(toAddr(c, r));
  return out;
}

export function refsOf(ast) {
  const seen = new Set();
  const walk = (n) => {
    switch (n.t) {
      case "ref": seen.add(n.addr); break;
      case "range": for (const a of rangeAddrs(n)) seen.add(a); break;
      case "bin": walk(n.l); walk(n.r); break;
      case "un": walk(n.e); break;
      case "call": n.args.forEach(walk); break;
    }
  };
  walk(ast);
  return [...seen];
}

const isErr = (v) => typeof v === "string" && v.startsWith("#");
const NUM = /^[+-]?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?$/;

function toNum(v) {
  if (isErr(v)) return v;
  if (v === null) return 0;
  if (typeof v === "boolean") return v ? 1 : 0;
  if (typeof v === "number") return v;
  const s = v.trim();
  return NUM.test(s) ? Number(s) : "#VALUE!";
}

function toBool(v) {
  if (isErr(v)) return v;
  if (v === null) return false;
  if (typeof v === "boolean") return v;
  if (typeof v === "number") return v !== 0;
  const s = v.toUpperCase();
  return s === "TRUE" ? true : s === "FALSE" ? false : "#VALUE!";
}

function toText(v) {
  if (isErr(v)) return v;
  if (v === null) return "";
  if (typeof v === "boolean") return v ? "TRUE" : "FALSE";
  return String(v);
}

const finite = (n) => (Number.isFinite(n) ? n : "#NUM!");
const rank = (v) => (typeof v === "number" ? 0 : typeof v === "string" ? 1 : 2);

function compare(a, b) {
  if (a === null && b === null) return 0;
  if (a === null) a = b === null ? null : typeof b === "number" ? 0 : typeof b === "string" ? "" : false;
  else if (b === null) b = typeof a === "number" ? 0 : typeof a === "string" ? "" : false;
  if (rank(a) !== rank(b)) return rank(a) - rank(b);
  if (typeof a === "string") {
    a = a.toLowerCase();
    b = b.toLowerCase();
  }
  return a < b ? -1 : a > b ? 1 : 0;
}

function round(x, d) {
  d = Math.trunc(d);
  const abs = Math.abs(x);
  let r;
  const s = String(abs);
  if (!s.includes("e") && Math.abs(d) < 300) r = Number(Math.round(Number(`${s}e${d}`)) + `e${-d}`);
  else r = Math.round(abs * 10 ** d) / 10 ** d;
  return finite(Math.sign(x) * r);
}

export function evaluate(ast, lookup) {
  const ev = (n) => {
    switch (n.t) {
      case "num": case "str": case "bool": return n.v;
      case "ref": return lookup(n.addr);
      case "range": return "#VALUE!";
      case "name": return "#NAME?";
      case "un": {
        const x = toNum(ev(n.e));
        if (typeof x === "string") return x;
        return n.op === "-" ? finite(-x) : x;
      }
      case "bin": return binary(n);
      case "call": return call(n);
    }
  };

  const binary = (n) => {
    const a = ev(n.l), b = ev(n.r);
    if (isErr(a)) return a;
    if (isErr(b)) return b;
    switch (n.op) {
      case "&": return toText(a) + toText(b);
      case "=": return compare(a, b) === 0;
      case "<>": return compare(a, b) !== 0;
      case "<": return compare(a, b) < 0;
      case ">": return compare(a, b) > 0;
      case "<=": return compare(a, b) <= 0;
      case ">=": return compare(a, b) >= 0;
    }
    const x = toNum(a);
    if (typeof x === "string") return x;
    const y = toNum(b);
    if (typeof y === "string") return y;
    switch (n.op) {
      case "+": return finite(x + y);
      case "-": return finite(x - y);
      case "*": return finite(x * y);
      case "/": return y === 0 ? "#DIV/0!" : finite(x / y);
      case "^": return finite(x ** y);
    }
  };

  // Calls fn(value) for each value of an argument; ranges are expanded. Returns an error to stop early.
  const values = (arg) => (arg.t === "range" ? rangeAddrs(arg).map((a) => lookup(a)) : null);

  const call = (n) => {
    const { name, args } = n;
    const arity = (min, max = min) => args.length >= min && args.length <= max;
    const scalar = (k) => (args[k].t === "range" ? "#VALUE!" : ev(args[k]));
    switch (name) {
      case "SUM": case "AVERAGE": case "MIN": case "MAX": {
        const nums = [];
        for (const arg of args) {
          const vs = values(arg);
          if (vs) {
            for (const v of vs) {
              if (isErr(v)) return v;
              if (typeof v === "number") nums.push(v);
            }
          } else {
            const x = toNum(ev(arg));
            if (typeof x === "string") return x;
            nums.push(x);
          }
        }
        if (name === "SUM") return finite(nums.reduce((s, x) => s + x, 0));
        if (name === "AVERAGE") {
          return nums.length ? finite(nums.reduce((s, x) => s + x, 0) / nums.length) : "#DIV/0!";
        }
        if (!nums.length) return 0;
        return name === "MIN" ? Math.min(...nums) : Math.max(...nums);
      }
      case "COUNT": {
        let c = 0;
        for (const arg of args) {
          const vs = values(arg);
          if (vs) c += vs.filter((v) => typeof v === "number").length;
          else if (typeof ev(arg) === "number") c++;
        }
        return c;
      }
      case "IF": {
        if (!arity(2, 3)) return "#VALUE!";
        const c = toBool(scalar(0));
        if (typeof c === "string") return c;
        if (c) return scalar(1);
        return args.length > 2 ? scalar(2) : false;
      }
      case "AND": case "OR": {
        if (!arity(1, Infinity)) return "#VALUE!";
        const bs = [];
        for (const arg of args) {
          const vs = values(arg);
          if (vs) {
            for (const v of vs) {
              if (isErr(v)) return v;
              if (typeof v === "number" || typeof v === "boolean") bs.push(v !== 0 && v !== false);
            }
          } else {
            const b = toBool(ev(arg));
            if (typeof b === "string") return b;
            bs.push(b);
          }
        }
        return name === "AND" ? bs.every(Boolean) : bs.some(Boolean);
      }
      case "NOT": {
        if (!arity(1)) return "#VALUE!";
        const b = toBool(scalar(0));
        return typeof b === "string" ? b : !b;
      }
      case "ROUND": {
        if (!arity(2)) return "#VALUE!";
        const x = toNum(scalar(0));
        if (typeof x === "string") return x;
        const d = toNum(scalar(1));
        if (typeof d === "string") return d;
        return round(x, d);
      }
      case "ABS": {
        if (!arity(1)) return "#VALUE!";
        const x = toNum(scalar(0));
        return typeof x === "string" ? x : Math.abs(x);
      }
      case "LEN": case "UPPER": case "LOWER": {
        if (!arity(1)) return "#VALUE!";
        const s = toText(scalar(0));
        if (isErr(s)) return s;
        return name === "LEN" ? s.length : name === "UPPER" ? s.toUpperCase() : s.toLowerCase();
      }
      case "CONCAT": {
        let out = "";
        for (const arg of args) {
          for (const v of values(arg) ?? [ev(arg)]) {
            if (isErr(v)) return v;
            out += toText(v);
          }
        }
        return out;
      }
      default: return "#NAME?";
    }
  };

  return ev(ast);
}
