import { parseFormula, refsOf, evaluate } from "./formula.mjs";
import { parseAddr, toAddr, colIndex } from "./addr.mjs";

export function valueOf(raw) {
  if (raw === "" || raw == null) return null;
  const t = raw.trim();
  if (t !== "" && Number.isFinite(Number(t))) return Number(t);
  const u = t.toUpperCase();
  if (u === "TRUE") return true;
  if (u === "FALSE") return false;
  if (raw.startsWith("'")) return raw.slice(1);
  return raw;
}

const key = (addr) => { const a = parseAddr(addr); return a.row * 1e6 + a.col; };

// Expands a reference (a cell or an "A1:B2" range) into normalized addresses.
function expand(ref) {
  const parts = String(ref).replace(/\$/g, "").split(":");
  const a = parseAddr(parts[0]), b = parseAddr(parts[parts.length - 1]);
  const out = [];
  for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++)
    for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++) out.push(toAddr(c, r));
  return out;
}

function parseCells(sheet) {
  const formulas = new Map(); // addr -> { ast, deps: Set } or { error: true }
  for (const [addr, raw] of sheet.cells) {
    if (!raw.startsWith("=")) continue;
    let ast;
    try { ast = parseFormula(raw); } catch { formulas.set(addr, { error: true, deps: new Set() }); continue; }
    const deps = new Set();
    try { for (const r of refsOf(ast)) for (const d of expand(r)) deps.add(d); } catch { /* bad refs: evaluate reports */ }
    formulas.set(addr, { ast, deps });
  }
  return formulas;
}

function cycleCells(formulas) {
  // iterative Tarjan over formula cells
  const index = new Map(), low = new Map(), onStack = new Set(), stack = [], cyc = new Set();
  let n = 0;
  for (const root of formulas.keys()) {
    if (index.has(root)) continue;
    const work = [[root, formulas.get(root).deps[Symbol.iterator]()]];
    index.set(root, n); low.set(root, n++); stack.push(root); onStack.add(root);
    while (work.length) {
      const [v, it] = work[work.length - 1];
      const nx = it.next();
      if (!nx.done) {
        const w = nx.value;
        if (!formulas.has(w)) continue;
        if (w === v) cyc.add(v);
        if (!index.has(w)) {
          index.set(w, n); low.set(w, n++); stack.push(w); onStack.add(w);
          work.push([w, formulas.get(w).deps[Symbol.iterator]()]);
        } else if (onStack.has(w)) low.set(v, Math.min(low.get(v), index.get(w)));
      } else {
        work.pop();
        if (work.length) { const p = work[work.length - 1][0]; low.set(p, Math.min(low.get(p), low.get(v))); }
        if (low.get(v) === index.get(v)) {
          const comp = [];
          let w;
          do { w = stack.pop(); onStack.delete(w); comp.push(w); } while (w !== v);
          if (comp.length > 1) for (const c of comp) cyc.add(c);
        }
      }
    }
  }
  return cyc;
}

// Kahn's algorithm over `nodes`, ties broken by row then column.
function topo(nodes, formulas) {
  const set = new Set(nodes), indeg = new Map(), rev = new Map();
  for (const v of nodes) {
    let d = 0;
    for (const w of formulas.get(v).deps) if (set.has(w)) { d++; (rev.get(w) ?? rev.set(w, []).get(w)).push(v); }
    indeg.set(v, d);
  }
  const heap = [];
  const less = (a, b) => key(a) < key(b);
  const push = (x) => {
    let i = heap.push(x) - 1;
    while (i > 0) { const p = (i - 1) >> 1; if (!less(heap[i], heap[p])) break; [heap[i], heap[p]] = [heap[p], heap[i]]; i = p; }
  };
  const pop = () => {
    const top = heap[0], last = heap.pop();
    if (heap.length) {
      heap[0] = last;
      for (let i = 0; ;) {
        let m = i; const l = 2 * i + 1, r = l + 1;
        if (l < heap.length && less(heap[l], heap[m])) m = l;
        if (r < heap.length && less(heap[r], heap[m])) m = r;
        if (m === i) break;
        [heap[i], heap[m]] = [heap[m], heap[i]]; i = m;
      }
    }
    return top;
  };
  for (const v of nodes) if (indeg.get(v) === 0) push(v);
  const order = [];
  while (heap.length) {
    const v = pop();
    order.push(v);
    for (const u of rev.get(v) ?? []) { indeg.set(u, indeg.get(u) - 1); if (indeg.get(u) === 0) push(u); }
  }
  return order;
}

export function computeAll(sheet) {
  const formulas = parseCells(sheet);
  const cyc = cycleCells(formulas);
  const values = new Map();
  for (const [addr, raw] of sheet.cells) if (!formulas.has(addr)) values.set(addr, valueOf(raw));
  for (const a of cyc) values.set(a, "#CYCLE!");
  const lookup = (a) => values.get(String(a).replace(/\$/g, "").toUpperCase()) ?? null;
  const live = [];
  for (const [addr, f] of formulas) {
    if (f.error) values.set(addr, "#ERROR!");
    else if (!cyc.has(addr)) live.push(addr);
  }
  for (const addr of topo(live, formulas)) values.set(addr, evaluate(formulas.get(addr).ast, lookup));
  const out = new Map();
  for (const addr of sheet.cells.keys()) out.set(addr, values.get(addr));
  return out;
}

export function dependents(sheet, addr) {
  const target = toAddr(parseAddr(addr).col, parseAddr(addr).row);
  const formulas = parseCells(sheet);
  const cyc = cycleCells(formulas);
  const rev = new Map();
  for (const [v, f] of formulas) for (const d of f.deps) (rev.get(d) ?? rev.set(d, []).get(d)).push(v);
  const seen = new Set([target]), stack = [target], found = [];
  while (stack.length) {
    for (const u of rev.get(stack.pop()) ?? []) if (!seen.has(u)) { seen.add(u); stack.push(u); found.push(u); }
  }
  return topo(found.filter((a) => !cyc.has(a)), formulas);
}
