import { parseAddr, toAddr, colIndex, colName } from "./addr.mjs";
import { getCell, setCell } from "./sheet.mjs";
import { valueOf } from "./recalc.mjs";

const parseRange = (range) => {
  const [a, b] = range.split(":");
  const p = parseAddr(a), q = parseAddr(b ?? a);
  return { c1: Math.min(p.col, q.col), c2: Math.max(p.col, q.col), r1: Math.min(p.row, q.row), r2: Math.max(p.row, q.row) };
};

const isEmpty = (v) => v == null || v === "";
const rank = (v) => (typeof v === "number" ? 0 : typeof v === "string" ? 1 : 2);

// Orders non-empty values: numbers, then strings (case-insensitive), then booleans (false first).
function compareValues(a, b) {
  const ra = rank(a), rb = rank(b);
  if (ra !== rb) return ra - rb;
  if (ra === 0) return a - b;
  if (ra === 1) {
    const x = a.toLowerCase(), y = b.toLowerCase();
    return x < y ? -1 : x > y ? 1 : 0;
  }
  return Number(a) - Number(b);
}

export function sortRange(sheet, range, keys, options = {}) {
  const { c1, c2, r1, r2 } = parseRange(range);
  const start = options.header ? r1 + 1 : r1;
  const rows = [];
  for (let r = start; r <= r2; r++) {
    const raws = [];
    for (let c = c1; c <= c2; c++) raws.push(getCell(sheet, toAddr(c, r)));
    const vals = keys.map((k) => {
      const col = colIndex(k.col);
      return col >= c1 && col <= c2 ? valueOf(raws[col - c1]) : null;
    });
    rows.push({ raws, vals, idx: r });
  }
  rows.sort((x, y) => {
    for (let i = 0; i < keys.length; i++) {
      const a = x.vals[i], b = y.vals[i];
      const ea = isEmpty(a), eb = isEmpty(b);
      if (ea || eb) {
        if (ea && eb) continue;
        return ea ? 1 : -1;
      }
      const d = compareValues(a, b);
      if (d) return keys[i].desc ? -d : d;
    }
    return x.idx - y.idx;
  });
  rows.forEach((row, i) => {
    for (let c = c1; c <= c2; c++) setCell(sheet, toAddr(c, start + i), row.raws[c - c1]);
  });
}

export function pivot(values, range, { rows, value, agg }) {
  const { c1, c2, r1, r2 } = parseRange(range);
  const find = (name) => {
    for (let c = c1; c <= c2; c++) if (String(values.get(toAddr(c, r1))) === String(name)) return c;
    throw new Error(`no such column: ${name}`);
  };
  const kc = find(rows), vc = find(value);
  const groups = new Map();
  for (let r = r1 + 1; r <= r2; r++) {
    let key = values.get(toAddr(kc, r));
    if (isEmpty(key)) key = null;
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(values.get(toAddr(vc, r)));
  }
  const aggregate = (vs) => {
    if (agg === "count") return vs.filter((v) => !isEmpty(v)).length;
    const nums = vs.filter((v) => typeof v === "number");
    if (agg === "sum") return nums.reduce((s, n) => s + n, 0);
    if (!nums.length) return null;
    if (agg === "avg") return nums.reduce((s, n) => s + n, 0) / nums.length;
    if (agg === "min") return Math.min(...nums);
    if (agg === "max") return Math.max(...nums);
    throw new Error(`unknown aggregation: ${agg}`);
  };
  const keys = [...groups.keys()].filter((k) => k !== null).sort(compareValues);
  if (groups.has(null)) keys.push(null);
  return keys.map((k) => ({ key: k === null ? "(blank)" : k, value: aggregate(groups.get(k)) }));
}
